class HAStorageCenter extends HTMLElement {
  constructor(){super();this.attachShadow({mode:"open"});this._tab="overview";}
  set hass(h){this._hass=h;this.render();}
  num(id){const s=this._hass?.states[id];if(!s)return 0;let v=String(s.state||"");if(v==="unknown"||v==="unavailable")return 0;let n=parseFloat(v.replace(",",".").replace(/[^\d.-]/g,""));return Number.isFinite(n)?n:0;}
  txt(id){return this._hass?.states[id]?.state||"-";}
  fmtDate(v){if(!v||v==="-"||v==="unknown")return "-";const d=new Date(v);if(isNaN(d))return String(v).split(".")[0].replace(" +0300","");return d.toLocaleString("tr-TR",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"});}
  render(){
    const used=this.num("sensor.system_monitor_disk_kullanimi");
    const free=this.num("sensor.system_monitor_bos_disk");
    const total=used+free;
    const pct=this.num("sensor.system_monitor_disk_kullanimi_2");
    const cpu=this.num("sensor.system_monitor_islemci_kullanimi");
    const ramMB=this.num("sensor.system_monitor_hafiza_kullanimi");
    const ramPct=this.num("sensor.system_monitor_hafiza_kullanimi_2");
    const net=this.num("sensor.system_monitor_eth0_de_ag_verimi");
    const frig=this.num("sensor.frigate_kayit_boyutu")/1024/1024/1024;
    const oldest=this.fmtDate(this.txt("sensor.frigate_en_eski_kayit"));
    const dash=440-(440*Math.min(100,pct)/100);
    this.shadowRoot.innerHTML=`<style>:host{display:block;font-family:Inter,system-ui}.card{background:radial-gradient(circle at top left,#2b5bff55,transparent 42%),linear-gradient(145deg,#0a0f1f,#142241);color:#fff;border-radius:28px;padding:24px;box-shadow:0 20px 45px rgba(0,0,0,.45)}.head{display:flex;justify-content:space-between;align-items:center}.live{background:#103826;color:#6cf59a;padding:8px 14px;border-radius:999px;font-weight:700}.grid{display:grid;grid-template-columns:220px 1fr;gap:20px;margin-top:18px}.ring{position:relative;display:flex;justify-content:center;align-items:center}svg{width:190px;height:190px;transform:rotate(-90deg)}.center{position:absolute;text-align:center}.num{font-size:48px;font-weight:800}.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.box{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08);border-radius:18px;padding:18px;backdrop-filter:blur(10px)}.box small{display:block;color:#9fb0d4;margin-bottom:6px}.box b{font-size:22px}.tabs{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:22px 0}.tab{padding:14px;border-radius:16px;background:rgba(255,255,255,.05);text-align:center;font-weight:700}.tab.a{background:linear-gradient(135deg,#5865ff,#7b4dff)}.panel{background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);border-radius:22px;padding:18px}.row{display:flex;justify-content:space-between;padding:14px 0;border-bottom:1px solid rgba(255,255,255,.06)}.row:last-child{border-bottom:none}@media(max-width:640px){.grid{grid-template-columns:1fr}.tabs{grid-template-columns:repeat(3,1fr)}}</style><div class=card><div class=head><div><div style="font-size:30px;font-weight:800">💽 Storage Center</div><div style="color:#97a3c8">Murat Edition · v0.4</div></div><div class=live>● CANLI</div></div><div class=grid><div class=ring><svg viewBox="0 0 180 180"><defs><linearGradient id=g><stop offset="0%" stop-color="#5a6cff"/><stop offset="100%" stop-color="#8b5cf6"/></linearGradient></defs><circle cx=90 cy=90 r=70 stroke="#24304a" stroke-width=14 fill=none/><circle cx=90 cy=90 r=70 stroke="url(#g)" stroke-width=14 fill=none stroke-linecap=round stroke-dasharray=440 stroke-dashoffset="${dash}"/></svg><div class=center><div class=num>${pct.toFixed(0)}%</div><div>Kullanılıyor</div></div></div><div class=stats><div class=box><small>🎥 Frigate</small><b>${frig.toFixed(1)} GB</b></div><div class=box><small>⚙️ CPU</small><b>${cpu.toFixed(0)}%</b></div><div class=box><small>🧠 RAM</small><b>${ramPct.toFixed(0)}%</b></div><div class=box><small>🌐 Ağ</small><b>${net.toFixed(3)} MB/s</b></div></div></div><div class=tabs><div class="tab a">📊 Genel</div><div class=tab>🎥 Frigate</div><div class=tab>📁 Dosyalar</div><div class=tab>📈 Tüketim</div><div class=tab>🧹 Temizlik</div></div><div class=panel><h2 style="margin-top:0">📊 Genel Bakış</h2><div class=row><span>Depolama Sağlığı</span><b>92/100</b></div><div class=row><span>En Eski Frigate Kaydı</span><b>${oldest}</b></div><div class=row><span>Frigate Klasörü</span><b>/media/frigate</b></div><div class=row><span>Canlı Güncelleme</span><b>30 saniye</b></div><div class=row><span>Kullanılan Disk</span><b>${used.toFixed(1)} GB</b></div><div class=row><span>Boş Disk</span><b>${free.toFixed(1)} GB</b></div><div class=row><span>Toplam Disk</span><b>${total.toFixed(1)} GB</b></div><div class=row><span>RAM</span><b>${ramMB.toFixed(0)} MB (${ramPct.toFixed(1)}%)</b></div><div class=row><span>CPU</span><b>${cpu.toFixed(0)}%</b></div><div class=row><span>Uptime</span><b>${this.txt("sensor.system_monitor_uptime")} gün</b></div></div></div>`;}
  static getStubConfig(){return{type:"custom:ha-storage-center"};}
}
customElements.get("ha-storage-center")||customElements.define("ha-storage-center",HAStorageCenter);
window.customCards=window.customCards||[];
window.customCards.push({type:"ha-storage-center",name:"Storage Center",preview:true,description:"Premium Storage Dashboard"});
